<template>
  <AdminLayout><main class="mx-auto max-w-7xl space-y-6">
    <AdminPageHeader eyebrow="TESORERÍA Y COBROS" title="Cuentas receptoras" description="Configura los destinos autorizados para recibir pagos."><template #action><button class="primary" @click="open()"><i class="pi pi-plus" />Nueva cuenta</button></template></AdminPageHeader>
    <section class="grid gap-3 sm:grid-cols-3">
      <article class="metric-card"><span>Total de cuentas</span><b>{{ meta.total || 0 }}</b><small>Dato global paginado</small></article>
      <article class="metric-card"><span>Activas en esta página</span><b>{{ activeOnPage }}</b><small>Indicador de registros cargados</small></article>
      <article class="metric-card"><span>Con QR en esta página</span><b>{{ qrOnPage }}</b><small>Solo aplica a Yape y Plin</small></article>
    </section>
    <form class="filter-card" @submit.prevent="load(1)"><label>Canal<select v-model="filters.channel" class="field"><option value="">Todos los canales</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="bank_transfer">Transferencia bancaria</option></select></label><label>Estado<select v-model="filters.is_active" class="field"><option value="">Todos los estados</option><option value="1">Activas</option><option value="0">Inactivas</option></select></label><div class="filter-actions"><button class="primary"><i class="pi pi-filter" />Aplicar</button><button type="button" class="secondary" @click="clear">Limpiar</button><AdminIconButton icon="pi pi-refresh" label="Actualizar cuentas" :disabled="loading" @click="load()" /></div></form>
    <div v-if="listError && !items.length" class="error" role="alert">{{ listError }}<button type="button" @click="load()">Reintentar</button></div>
    <div v-else-if="listError" class="error" role="status">{{ listError }}<button type="button" @click="load()">Reintentar</button></div>
    <div v-if="actionError" class="error" role="alert">{{ actionError }}</div>
    <section v-else class="table-card">
      <div class="overflow-x-auto desktop-table"><table class="min-w-[1050px] w-full"><thead><tr><th scope="col">Cuenta</th><th scope="col">Canal</th><th scope="col">Destino</th><th scope="col">QR</th><th scope="col">Configuración</th><th scope="col">Estado</th><th scope="col">Acciones</th></tr></thead><tbody>
        <template v-if="loading"><tr v-for="n in 5" :key="n"><td v-for="c in 7" :key="c"><span class="skeleton" /></td></tr></template>
        <template v-else-if="items.length"><tr v-for="item in items" :key="item.id"><td><div class="account-cell"><span class="channel-avatar"><i :class="channelIcon(item.channel)" /></span><span><b>{{ item.display_name }}</b><small>{{ item.code }}</small></span></div></td><td>{{ label(item.channel) }}</td><td><b>{{ item.holder_name }}</b><small>{{ destination(item) }}</small></td><td><AdminStatusBadge v-if="needsQr(item)" :active="item.has_qr" active-label="QR cargado" inactive-label="QR pendiente" /><span v-else class="muted">No requiere QR</span></td><td><AdminStatusBadge v-if="item.is_default" :active="true" active-label="Principal" /><span v-else class="muted">Secundaria</span></td><td><AdminStatusBadge :active="item.is_active" active-label="Activa" inactive-label="Inactiva" /></td><td><div class="actions"><button v-if="needsQr(item) && !item.has_qr" class="primary compact" @click="openQr(item)"><i class="pi pi-upload" />Cargar QR</button><button v-if="needsQr(item) && item.has_qr" class="secondary compact" @click="preview(item)"><i class="pi pi-eye" />Ver QR</button><button v-if="needsQr(item) && item.has_qr" class="secondary compact" @click="openQr(item)"><i class="pi pi-refresh" />Reemplazar QR</button><AdminIconButton v-if="!item.is_default" icon="pi pi-star" :label="`Establecer ${item.code} como principal`" @click="makeDefault(item)" /><AdminIconButton icon="pi pi-pencil" :label="`Editar ${item.code}`" @click="open(item)" /><AdminIconButton :icon="item.is_active ? 'pi pi-ban' : 'pi pi-check'" :label="item.is_active ? `Desactivar ${item.code}` : item.has_qr || !needsQr(item) ? `Activar ${item.code}` : 'Debes cargar un QR antes de activar esta cuenta'" :disabled="needsQr(item) && !item.has_qr && !item.is_active" @click="status(item)" /></div></td></tr></template>
        <tr v-else><td colspan="7"><AdminEmptyState title="No hay cuentas receptoras" :description="hasFilters ? 'No encontramos cuentas con los filtros seleccionados.' : 'Configura una cuenta para comenzar.'"><button class="primary mt-4" @click="open()">Nueva cuenta</button></AdminEmptyState></td></tr>
      </tbody></table></div>
      <div v-if="!loading" class="mobile-list"><article v-for="item in items" :key="item.id" class="mobile-account"><div class="account-cell"><span class="channel-avatar"><i :class="channelIcon(item.channel)" /></span><span><b>{{ item.display_name }}</b><small>{{ item.code }} · {{ label(item.channel) }}</small></span></div><p><b>{{ item.holder_name }}</b><br>{{ destination(item) }}</p><div class="flex flex-wrap gap-2"><AdminStatusBadge :active="item.is_active" active-label="Activa" inactive-label="Inactiva" /><AdminStatusBadge v-if="needsQr(item)" :active="item.has_qr" active-label="QR cargado" inactive-label="QR pendiente" /></div><div class="actions mt-3"><button v-if="needsQr(item) && !item.has_qr" class="primary compact" @click="openQr(item)">Cargar QR</button><AdminIconButton icon="pi pi-pencil" :label="`Editar ${item.code}`" @click="open(item)" /><AdminIconButton :icon="item.is_active ? 'pi pi-ban' : 'pi pi-check'" :label="item.is_active ? `Desactivar ${item.code}` : `Activar ${item.code}`" :disabled="needsQr(item) && !item.has_qr && !item.is_active" @click="status(item)" /></div></article></div>
      <AdminPagination :page="meta.current_page || 1" :last-page="meta.last_page || 1" :loading="loading" :summary="summary" @change="load" />
    </section>

    <div v-if="modal" class="overlay" role="dialog" aria-modal="true" aria-labelledby="account-modal-title"><form class="modal" @submit.prevent="save"><header><i class="pi pi-wallet" /><div><h2 id="account-modal-title">{{ form.id ? 'Editar cuenta receptora' : 'Nueva cuenta receptora' }}</h2><p>{{ form.id ? 'Actualiza únicamente la información permitida.' : 'Configura los datos de recepción.' }}</p></div><button type="button" class="close" aria-label="Cerrar modal de cuenta" @click="closeModal">×</button></header><div class="modal-body"><p v-if="!form.id && needsQr(form)" class="info">Las cuentas Yape y Plin se registran primero como inactivas. Luego debes cargar su QR para poder activarlas.</p><div class="form-grid"><label>Código<input v-model="form.code" class="field" :disabled="!!form.id" required></label><label>Canal<select v-model="form.channel" class="field" :disabled="!!form.id"><option value="yape">Yape</option><option value="plin">Plin</option><option value="bank_transfer">Transferencia bancaria</option></select></label><label>Nombre<input v-model="form.display_name" class="field" required></label><label>Titular<input v-model="form.holder_name" class="field" required></label><template v-if="form.channel === 'bank_transfer'"><label>Banco<input v-model="form.bank_name" class="field"></label><label>Cuenta <small>{{ form.account_number_masked }}</small><input v-model="form.account_number" class="field"></label><label>CCI <small>{{ form.cci_masked }}</small><input v-model="form.cci" class="field"></label><label class="check"><input v-model="form.is_active" type="checkbox"> Activa</label><label class="check"><input v-model="form.is_default" type="checkbox" :disabled="!form.is_active"> Predeterminada</label></template><template v-else><label>Teléfono <small>{{ form.phone_masked }}</small><input v-model="form.phone" class="field"></label><p class="info">El flujo continúa con la carga del QR; la activación requiere confirmación posterior.</p></template></div></div><footer><button type="button" class="secondary" :disabled="saving" @click="closeModal">Cancelar</button><button class="primary" :disabled="saving">{{ saving ? 'Guardando…' : form.id ? 'Guardar cambios' : 'Guardar y continuar' }}</button></footer></form></div>
    <div v-if="qrModal" class="overlay" role="dialog" aria-modal="true" aria-labelledby="qr-modal-title"><section class="modal"><header><i class="pi pi-qrcode" /><div><h2 id="qr-modal-title">{{ selected?.has_qr ? 'Reemplazar QR' : 'Cargar QR' }}</h2><p>1. Datos registrados · 2. QR pendiente · 3. Activación pendiente</p></div><button class="close" aria-label="Cerrar carga de QR" @click="closeQr">×</button></header><div class="modal-body"><p class="info">Selecciona una imagen PNG, JPEG o WebP. No se activará la cuenta automáticamente.</p><input ref="file" type="file" accept="image/png,image/jpeg,image/webp" :disabled="uploading" @change="handleQrSelection"><p v-if="hasSelectedQrFile">Archivo seleccionado: <b>{{ selectedQrFile.name }}</b></p><p v-if="qrError" class="error">{{ qrError }}</p><p v-if="uploading">Cargando QR…</p></div><footer><button class="secondary" :disabled="uploading" @click="closeQr">Cancelar</button><button class="secondary" :disabled="uploading" @click="file?.click()">Seleccionar archivo</button><button class="primary" :disabled="uploading || !hasSelectedQrFile" @click="submitQr">Subir QR</button></footer></section></div>
    <div v-if="qrUrl" class="overlay" role="dialog" aria-modal="true" aria-labelledby="preview-modal-title"><section class="modal preview"><header><i class="pi pi-eye" /><div><h2 id="preview-modal-title">Vista previa del QR</h2><p>Imagen privada de la cuenta receptora.</p></div><button class="close" aria-label="Cerrar vista previa del QR" @click="closePreview">×</button></header><div class="modal-body"><img :src="qrUrl" alt="QR de cuenta receptora" class="qr-image"></div><footer><button class="secondary" @click="closePreview">Cerrar</button></footer></section></div>
  </main></AdminLayout>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useToast } from 'primevue/usetoast'
import api from '@/api'
import AdminLayout from '@/layouts/AdminLayout.vue'
import AdminPageHeader from '@/components/admin/AdminPageHeader.vue'
import AdminStatusBadge from '@/components/admin/AdminStatusBadge.vue'
import AdminIconButton from '@/components/admin/AdminIconButton.vue'
import AdminEmptyState from '@/components/admin/AdminEmptyState.vue'
import AdminPagination from '@/components/admin/AdminPagination.vue'
const toast = useToast(); const items = ref([]), meta = ref({}), loading = ref(false), listError = ref(''), actionError = ref(''), formError = ref(''), fieldErrors = ref({}), previewError = ref(''), modal = ref(false), saving = ref(false), qrModal = ref(false), uploading = ref(false), file = ref(), selected = ref(), selectedQrFile = ref(null), qrError = ref(''), qrUrl = ref(''), form = ref({})
const filters = ref({ channel: '', is_active: '' })
const hasFilters = computed(() => Object.values(filters.value).some(Boolean)); const activeOnPage = computed(() => items.value.filter(i => i.is_active).length); const qrOnPage = computed(() => items.value.filter(i => i.has_qr).length); const hasSelectedQrFile = computed(() => { const selectedFile = selectedQrFile.value; return typeof globalThis.File === 'function' && selectedFile instanceof globalThis.File }); const summary = computed(() => meta.value.total ? `Mostrando ${meta.value.from}–${meta.value.to} de ${meta.value.total} cuentas` : 'Sin registros')
const label = c => ({ yape: 'Yape', plin: 'Plin', bank_transfer: 'Transferencia bancaria' }[c] || c); const channelIcon = c => ({ yape: 'pi pi-mobile', plin: 'pi pi-mobile', bank_transfer: 'pi pi-building-columns' }[c] || 'pi pi-wallet'); const needsQr = i => ['yape', 'plin'].includes(i?.channel); const destination = i => i.phone_masked || i.account_number_masked || i.cci_masked || 'Sin dato configurado'; const message = e => e.response?.data?.message || Object.values(e.response?.data?.errors || {})[0]?.[0] || 'No se pudo completar la operación.'
let request = 0
async function load(page = meta.value.current_page || 1) { if (loading.value) return; const id = ++request; loading.value = true; listError.value = ''; try { const { data } = await api.get('/admin/treasury/receiving-accounts', { params: { page, ...Object.fromEntries(Object.entries(filters.value).filter(([, value]) => value !== '')) } }); if (id === request) { items.value = data.data || []; meta.value = data } } catch (e) { if (id === request) { listError.value = message(e); if (items.value.length) toast.add({ severity: 'error', summary: 'No se pudo actualizar el listado', detail: listError.value, life: 5000 }) } } finally { if (id === request) loading.value = false } }
function clear() { filters.value = { channel: '', is_active: '' }; load(1) }; function closeModal(force = false) { if (saving.value && !force) return; modal.value = false; form.value = {} }; function open(item) { form.value = item ? { ...item, phone: '', account_number: '', cci: '' } : { code: '', channel: 'yape', display_name: '', holder_name: '', currency: 'PEN', phone: '', bank_name: '', account_number: '', cci: '', sort_order: 0, is_active: false, is_default: false, has_qr: false }; modal.value = true }
function payload() { const data = { ...form.value }; ['phone_masked', 'account_number_masked', 'cci_masked', 'has_qr', 'qr_path', 'qr_disk', 'created_at', 'updated_at'].forEach(key => delete data[key]); if (form.value.id) { delete data.code; delete data.channel; ['phone', 'account_number', 'cci'].forEach(key => { if (!data[key]) delete data[key] }) } if (!data.is_active) data.is_default = false; return data }
async function save() { if (saving.value) return; saving.value = true; formError.value = ''; fieldErrors.value = {}; try { const { data } = form.value.id ? await api.put(`/admin/treasury/receiving-accounts/${form.value.id}`, payload()) : await api.post('/admin/treasury/receiving-accounts', payload()); const created = data.data || data; const isNewQrAccount = !form.value.id && needsQr(form.value); toast.add({ severity: 'success', summary: form.value.id ? 'Cuenta actualizada' : 'Cuenta creada', life: 4000 }); closeModal(true); await load(); if (isNewQrAccount && created?.id) openQr(created) } catch (e) { fieldErrors.value = e.response?.data?.errors || {}; formError.value = message(e); toast.add({ severity: 'error', summary: 'No se pudo guardar', detail: formError.value, life: 5000 }) } finally { saving.value = false } }
function openQr(item) { selected.value = item; selectedQrFile.value = null; qrError.value = ''; qrModal.value = true }; function closeQr() { if (uploading.value) return; qrModal.value = false; selected.value = undefined; selectedQrFile.value = null; qrError.value = ''; if (file.value) file.value.value = '' }
function handleQrSelection(event) { qrError.value = ''; const selectedFile = event?.target?.files?.[0] ?? null; selectedQrFile.value = typeof globalThis.File === 'function' && selectedFile instanceof globalThis.File ? selectedFile : null; if (!hasSelectedQrFile.value) qrError.value = 'Selecciona una imagen válida.' }
async function submitQr() { if (!hasSelectedQrFile.value) { qrError.value = 'Selecciona una imagen válida.'; return } if (uploading.value) return; uploading.value = true; const formData = new FormData(); formData.append('qr', selectedQrFile.value); try { await api.post(`/admin/treasury/receiving-accounts/${selected.value.id}/qr`, formData); uploading.value = false; closeQr(); await load(); toast.add({ severity: 'success', summary: 'QR cargado', detail: 'Ahora puedes activar la cuenta.', life: 4000 }) } catch (err) { qrError.value = message(err) } finally { uploading.value = false } }
async function preview(item) { previewError.value = ''; try { const response = await api.get(`/admin/treasury/receiving-accounts/${item.id}/qr`, { responseType: 'blob' }); if (!['image/png', 'image/jpeg', 'image/webp'].some(type => response.headers['content-type']?.includes(type))) throw Error(); closePreview(); qrUrl.value = URL.createObjectURL(response.data) } catch { previewError.value = 'No se pudo cargar el QR.'; toast.add({ severity: 'error', summary: 'Error de vista previa', detail: previewError.value, life: 5000 }) } }; function closePreview() { if (qrUrl.value) URL.revokeObjectURL(qrUrl.value); qrUrl.value = '' }
async function status(item) { actionError.value = ''; try { await api.patch(`/admin/treasury/receiving-accounts/${item.id}/status`, { is_active: !item.is_active }); await load(); toast.add({ severity: 'success', summary: item.is_active ? 'Cuenta desactivada' : 'Cuenta activada', life: 4000 }) } catch (e) { actionError.value = message(e); toast.add({ severity: 'error', summary: 'Acción rechazada', detail: actionError.value, life: 5000 }) } }; async function makeDefault(item) { if (item.is_default) return; actionError.value = ''; try { await api.patch(`/admin/treasury/receiving-accounts/${item.id}/default`, { is_default: true }); await load(); toast.add({ severity: 'success', summary: 'Cuenta establecida como principal', life: 4000 }) } catch (e) { actionError.value = message(e); toast.add({ severity: 'error', summary: 'No se pudo establecer como principal', detail: actionError.value, life: 5000 }) } }
onMounted(load); onBeforeUnmount(closePreview)
</script>

<style scoped>
.metric-card,.filter-card,.table-card{border:1px solid #e2e8f0;border-radius:1rem;background:#fff;padding:1rem;box-shadow:0 1px 3px #0f172a0d}.metric-card span,.metric-card small,td small{display:block;color:#64748b}.metric-card b{display:block;font-size:1.5rem;color:#0f172a}.filter-card{display:flex;gap:1rem;align-items:end;flex-wrap:wrap}.filter-card label{display:grid;gap:.35rem;font-size:.85rem;font-weight:600}.filter-actions,.actions{display:flex;gap:.4rem;align-items:center;flex-wrap:wrap}.field{min-width:13rem;border:1px solid #cbd5e1;border-radius:.6rem;padding:.6rem}.primary,.secondary{display:inline-flex;gap:.4rem;align-items:center;justify-content:center;min-height:2.5rem;border-radius:.6rem;padding:.55rem .8rem}.primary{background:#0f766e;color:white}.secondary{background:#f1f5f9;color:#334155}.compact{font-size:.8rem}.table-card{padding:0;overflow:hidden}th,td{padding:1rem;text-align:left;vertical-align:middle;border-bottom:1px solid #e2e8f0}th{font-size:.75rem;text-transform:uppercase;color:#475569}.account-cell{display:flex;gap:.75rem;align-items:center}.channel-avatar{display:grid;width:2.5rem;height:2.5rem;place-items:center;border-radius:999px;background:#ccfbf1;color:#0f766e}.muted{font-size:.85rem;color:#64748b}.skeleton{display:block;height:1.2rem;border-radius:.4rem;background:#e2e8f0}.error{display:flex;justify-content:space-between;gap:1rem;padding:1rem;border-radius:.75rem;background:#fef2f2;color:#991b1b}.mobile-list{display:none}.overlay{position:fixed;inset:0;z-index:80;display:flex;align-items:center;justify-content:center;padding:1rem;background:#0f172ab3}.modal{width:min(100%,44rem);max-height:calc(100vh - 2rem);display:flex;flex-direction:column;overflow:hidden;border:1px solid #e2e8f0;border-radius:1rem;background:white;box-shadow:0 25px 50px #02061780}.modal header{display:flex;gap:.75rem;align-items:start;padding:1.25rem;border-bottom:1px solid #e2e8f0}.modal header>i{font-size:1.4rem;color:#0f766e}.modal h2{font-weight:700}.modal header p{font-size:.85rem;color:#64748b}.close{margin-left:auto;width:2.5rem;height:2.5rem;border-radius:.5rem;font-size:1.5rem}.modal-body{overflow-y:auto;padding:1.25rem}.form-grid{display:grid;gap:1rem;grid-template-columns:repeat(2,minmax(0,1fr))}.form-grid label{display:grid;gap:.35rem;font-weight:600}.form-grid .check{display:flex;align-items:center;gap:.5rem}.info{margin-bottom:1rem;border-radius:.6rem;background:#ecfeff;padding:.75rem;color:#155e75;font-size:.9rem}.modal footer{display:flex;justify-content:flex-end;gap:.75rem;padding:1rem 1.25rem;border-top:1px solid #e2e8f0}.qr-image{display:block;max-width:100%;max-height:65vh;object-fit:contain;margin:auto}@media(max-width:640px){.desktop-table{display:none}.mobile-list{display:grid;gap:.75rem;padding:1rem}.mobile-account{border:1px solid #e2e8f0;border-radius:.75rem;padding:1rem}.form-grid{grid-template-columns:1fr}.modal footer{flex-direction:column-reverse}.modal footer button{width:100%}.filter-card>*{width:100%}.filter-actions{width:100%}.field{width:100%}}
</style>
